Chats.switchChat = function (roomId) {
	// Allow empty arg for return to chat list/close chat
	if (!roomId) {
		roomId = '';
	}
	Chats.destroyAutoComplete(ajaxify.data.roomId);
	socket.emit('modules.chats.leave', ajaxify.data.roomId);
	const url = 'user/' + ajaxify.data.userslug + '/chats/' + roomId + window.location.search;
	if (!self.fetch) {
		return ajaxify.go(url);
	}
	const params = new URL(document.location).searchParams;
	params.set('switch', 1);
	const dataUrl = `${config.relative_path}/api/user/${ajaxify.data.userslug}/chats/${roomId}?${params.toString()}`;
	fetch(dataUrl, { credentials: 'include' })
		.then(async function (response) {
			if (!response.ok) {
				return console.warn('[search] Received ' + response.status);
			}
			const payload = await response.json();
			const html = await app.parseAndTranslate('partials/chats/message-window', payload);
			const mainWrapper = components.get('chat/main-wrapper');
			mainWrapper.html(html);
			mainWrapper.attr('data-roomid', roomId);
			chatNavWrapper = $('[component="chat/nav-wrapper"]');
			html.find('.timeago').timeago();
			ajaxify.data = { ...ajaxify.data, ...payload, roomId: roomId };
			ajaxify.updateTitle(ajaxify.data.title);
			$('body').toggleClass('chat-loaded', !!roomId);

		_raw: params,
		to: email,
		from: meta.config['email:from'] || `no-reply@${getHostname()}`,
		from_name: meta.config['email:from_name'] || 'NodeBB',
		subject: `[${meta.config.title}] ${_.unescape(subject)}`,
		html: html,
		plaintext: htmlToText(html, {
			tags: { img: { format: 'skip' } },
		}),
		template: template,
		uid: params.uid,
		pid: params.pid,
		fromUid: params.fromUid,
		headers: params.headers,
		rtl: params.rtl,
	});
	const usingFallback = !Plugins.hooks.hasListeners('filter:email.send') &&
		!Plugins.hooks.hasListeners('static:email.send');
	try {
		if (Plugins.hooks.hasListeners('filter:email.send')) {
			// Deprecated, remove in v1.19.0
			await Plugins.hooks.fire('filter:email.send', data);
		} else if (Plugins.hooks.hasListeners('static:email.send')) {
			await Plugins.hooks.fire('static:email.send', data);
		} else {
			await Emailer.sendViaFallback(data);
		}
	} catch (err) {
		if (err.code === 'ENOENT' && usingFallback) {
			Emailer.fallbackNotFound = true;
			throw new Error('[[error:sendmail-not-found]]');
		} else {
			throw err;
		}
	}
};

Emailer.sendViaFallback = async (data) => {
	// Some minor alterations to the data to conform to nodemailer standard
	data.text = data.plaintext;
	delete data.plaintext;

	// NodeMailer uses a combined "from"
	data.from = { name: data.from_name, address: data.from };
	delete data.from_name;
	await Emailer.fallbackTransport.sendMail(data);
};

